573→      if (!activeAgentId) return;
574→      // Optimistically add user message to local state
575→      updateAgent(activeAgentId, (prev) => ({
576→        ...prev,
577→        messages: [
578→          ...prev.messages,
579→          {
580→            id: nextId(),
581→            role: "user",
582→            content,
583→            timestamp: Date.now(),
584→          },
585→        ],
586→      }));
