607→
608→  /** Respond to an AskUserQuestion control request with the user's selections. */
609→  const respondToUserQuestion = useCallback(
610→    (requestId: string, answers: Record<string, string>) => {
611→      if (!activeAgentId) return;
612→      send({
613→        type: "control_response",
614→        agentId: activeAgentId,
615→        request_id: requestId,
616→        allow: true,
617→        answers,
618→      });
619→      updateAgent(activeAgentId, (prev) => ({
620→        ...prev,
621→        messages: prev.messages.map((m) =>
622→          m.userQuestion?.requestId === requestId
623→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
624→            : m
625→        ),
626→      }));
627→    },
628→    [send, activeAgentId, updateAgent]
629→  );
630→
631→  // ── Agent management actions ──────────────────────────────────────────────
632→
633→  const killAgent = useCallback(
634→    (agentId: string) => {
635→      send({ type: "kill_agent", agentId });
636→    },
637→    [send]
638→  );
639→
640→  const deleteAgent = useCallback(
641→    (agentId: string) => {
642→      send({ type: "delete_agent", agentId });
643→      // Deselect if we just deleted the active agent
644→      setActiveAgentId((prev) => (prev === agentId ? null : prev));
645→    },
646→    [send]
647→  );
648→
649→  const renameAgent = useCallback(
650→    (agentId: string, label: string) => {
651→      send({ type: "rename_agent", agentId, label });
652→    },
653→    [send]
654→  );
655→
656→  const clearHistory = useCallback(
657→    (agentId: string) => {
658→      send({ type: "clear_history", agentId });
659→    },
660→    [send]
661→  );
662→
663→  // ── Task actions ──────────────────────────────────────────────────────────
664→
665→  const createTask = useCallback(
666→    (title: string, description: string, priority: TaskPriority) => {
667→      send({ type: "create_task", title, description, priority });
