  1→/**
  2→ * Standalone WebSocket relay server for the thos dashboard.
  3→ *
  4→ * Runs on port 9900 alongside Next.js (started via `concurrently` in the
  5→ * `dev` script). It cannot be a Next.js API route because API routes don't
  6→ * support persistent WebSocket connections.
  7→ *
  8→ * ## Architecture
  9→ *
 10→ * Two WebSocket path families:
 11→ * - `/browser`          — the React dashboard connects here (supports multiple tabs).
 12→ * - `/claude/:agentId`  — each Claude CLI connects here (passed as `--sdk-url`).
 13→ *
 14→ * The server supports multiple concurrent agents, each tracked in the
 15→ * `agents` Map keyed by a short random ID.
 16→ *
 17→ * ## Connection flow (browser)
 18→ *
 19→ * On browser connect, the server sends two small messages:
 20→ * 1. `agent_list`  — metadata for all agents (sidebar).
 21→ * 2. `task_list`   — all tasks.
 22→ *
 23→ * Message histories are NOT sent eagerly. They are loaded lazily: the
 24→ * browser sends `{ type: "request_history", agentId }` when the user
 25→ * selects an agent, and the server responds with `message_history` for
 26→ * that single agent. This avoids sending megabytes of JSON on connect,
 27→ * which caused multi-minute loading times on mobile networks.
 28→ *
 29→ * Live messages for active agents are still broadcast to all browsers
 30→ * via `relay` messages in real time.
 31→ *
 32→ * ## Message flow (spawning)
 33→ *
 34→ * 1. Browser sends `{ type: "spawn", prompt }`.
 35→ * 2. Server creates agent entry, spawns `claude --sdk-url ws://localhost:9900/claude/<agentId>`.
 36→ * 3. CLI connects on `/claude/<agentId>`, sends `system/hook_started` then `system/hook_response`.
 37→ * 4. On `hook_response`, server forwards the pending prompt to the CLI.
 38→ * 5. CLI sends `system/init`, then `assistant` messages, then `result`.
 39→ * 6. All CLI messages are relayed to the browser as `{ type: "relay", agentId, message }`.
 40→ * 7. `control_request` messages (tool approval) are relayed to the browser;
 41→ *    the browser's `control_response` (with `agentId`) is forwarded back to the right CLI.
 42→ *
 43→ * ## Resilience features
 44→ *
 45→ * - **Server-side message history** — every relay message is stored per-agent.
 46→ * - **File persistence** — agent state + history persisted to disk, survives restarts.
 47→ * - **Multi-browser** — multiple tabs can connect simultaneously.
 48→ * - **tmux survival** — tmux sessions are NOT killed on server restart; CLI processes
 49→ *   can reconnect to the new server if they retry their WebSocket connection.
 50→ * - **Message queuing** — messages sent while CLI is disconnected are queued and flushed on reconnect.
 51→ * - **Disconnect notifications** — browser is notified of CLI disconnect/reconnect.
 52→ * - **Lazy history** — message histories loaded on demand per agent, not on connect.
 53→ */
 54→import { WebSocketServer, WebSocket } from "ws";
 55→import { execSync, spawn } from "child_process";
 56→import { randomBytes } from "crypto";
 57→import type { IncomingMessage } from "http";
 58→import type {
 59→  BrowserMessage,
 60→  ClaudeMessage,
 61→  ServerMessage,
 62→  AgentStatus,
 63→  AgentInfo,
 64→  Task,
 65→} from "../lib/types";
 66→import { SessionStore, type PersistedAgent } from "./session-store";
 67→import { TaskStore } from "./task-store";
 68→
 69→const PORT = 9900;
 70→const TMUX_SESSION_PREFIX = "thos-agent";
 71→
 72→/** Check if an IP is localhost or in the Tailscale CGNAT range (100.64.0.0/10). */
 73→function isAllowedIP(ip: string | undefined): boolean {
 74→  if (!ip) return false;
 75→  // Strip IPv6-mapped IPv4 prefix
 76→  const addr = ip.startsWith("::ffff:") ? ip.slice(7) : ip;
 77→  if (addr === "127.0.0.1" || addr === "::1" || addr === "localhost") return true;
 78→  // Tailscale CGNAT: 100.64.0.0/10 → 100.64.0.0 – 100.127.255.255
 79→  const parts = addr.split(".");
 80→  if (parts.length !== 4) return false;
 81→  const first = parseInt(parts[0], 10);
 82→  const second = parseInt(parts[1], 10);
 83→  return first === 100 && second >= 64 && second <= 127;
 84→}
 85→
 86→const wss = new WebSocketServer({
 87→  port: PORT,
 88→  verifyClient: (info) => {
 89→    const ip = info.req.socket.remoteAddress;
 90→    const allowed = isAllowedIP(ip);
 91→    if (!allowed) console.log(`[ws] rejected connection from ${ip}`);
 92→    return allowed;
 93→  },
 94→});
 95→const store = new SessionStore();
 96→
 97→// ── Multi-agent state ──────────────────────────────────────────────────────
 98→
 99→interface AgentState {
100→  agentId: string;
101→  claudeSocket: WebSocket | null;
102→  tmuxSession: string | null;
103→  pendingPrompt: string | null;
104→  status: AgentStatus;
105→  label: string;
106→  createdAt: number;
107→  /** Captured from system/init, used in subsequent user messages. */
108→  sessionId: string | null;
109→  /** Stores control_request inputs keyed by request_id, for building control_responses. */
110→  pendingControlRequests: Map<string, Record<string, unknown>>;
111→  /** All messages sent to the browser for this agent (source of truth). */
112→  messageHistory: ServerMessage[];
113→  /** Messages queued while CLI is disconnected, flushed on reconnect. */
114→  pendingMessages: string[];
115→}
116→
117→const agents = new Map<string, AgentState>();
118→const taskStore = new TaskStore();
119→const tasks = new Map<string, Task>();
120→
121→/** All active browser connections (supports multiple tabs). */
122→const browserSockets = new Set<WebSocket>();
123→
124→/** Generate a short random agent ID. */
125→function newAgentId(): string {
126→  return randomBytes(4).toString("hex");
127→}
128→
129→// ── tmux helpers ───────────────────────────────────────────────────────────
130→
131→/** Return the set of currently alive tmux session names matching the thos prefix. */
132→function listAliveTmuxSessions(): Set<string> {
133→  try {
134→    const output = execSync("tmux list-sessions -F '#{session_name}'", {
135→      encoding: "utf-8",
136→    }).trim();
137→    if (!output) return new Set();
138→    return new Set(output.split("\n").filter((s) => s.startsWith(TMUX_SESSION_PREFIX)));
139→  } catch {
140→    return new Set();
141→  }
142→}
143→
144→// ── Persistence helpers ────────────────────────────────────────────────────
145→
146→/** Build a PersistedAgent snapshot from live state. */
147→function toPersistedAgent(agent: AgentState): PersistedAgent {
148→  return {
149→    id: agent.agentId,
150→    state: {
151→      agentId: agent.agentId,
152→      status: agent.status,
153→      tmuxSession: agent.tmuxSession,
154→      label: agent.label,
155→      createdAt: agent.createdAt,
156→      sessionId: agent.sessionId,
157→    },
158→    messageHistory: agent.messageHistory,
159→  };
160→}
161→
162→/**
163→ * Compact a message history by deduplicating cumulative snapshots.
164→ * Keeps only the last version of each assistant/user message ID.
165→ * Called on restore to shrink legacy bloated histories.
166→ */
167→function compactHistory(history: ServerMessage[]): ServerMessage[] {
168→  // Build a map of msgId → last index
169→  const lastIndex = new Map<string, number>();
170→  for (let i = 0; i < history.length; i++) {
171→    const id = getRelayMessageId(history[i]);
172→    if (id) lastIndex.set(id, i);
173→  }
174→  // Keep only messages that are either non-deduplicable or the last occurrence
175→  return history.filter((msg, i) => {
176→    const id = getRelayMessageId(msg);
177→    if (!id) return true; // non-relay or no message ID — always keep
178→    return lastIndex.get(id) === i;
179→  });
180→}
181→
182→/** Persist agent state (debounced — use for streaming events). */
183→function persistAgent(agent: AgentState) {
184→  store.save(toPersistedAgent(agent));
185→}
186→
187→/** Persist agent state immediately (use for critical state changes). */
188→function persistAgentSync(agent: AgentState) {
189→  store.saveSync(toPersistedAgent(agent));
190→}
191→
192→// ── Restore from disk on startup ───────────────────────────────────────────
193→
194→function restoreAgents() {
195→  const persisted = store.loadAll();
196→  const aliveSessions = listAliveTmuxSessions();
197→
198→  for (const p of persisted) {
199→    const agent: AgentState = {
200→      agentId: p.state.agentId,
201→      claudeSocket: null,
202→      tmuxSession: p.state.tmuxSession,
203→      pendingPrompt: null,
204→      status: p.state.status,
205→      label: p.state.label,
206→      createdAt: p.state.createdAt,
207→      sessionId: p.state.sessionId,
208→      pendingControlRequests: new Map(),
209→      messageHistory: compactHistory(p.messageHistory),
210→      pendingMessages: [],
211→    };
212→
213→    // Determine status for agents that were active when the server last ran
214→    if (agent.status !== "done" && agent.status !== "error") {
215→      const tmuxAlive = agent.tmuxSession ? aliveSessions.has(agent.tmuxSession) : false;
216→      if (tmuxAlive) {
217→        // tmux session still alive — CLI may reconnect to this server
218→        agent.status = "disconnected";
219→        console.log(`[restore] agent ${agent.agentId} — tmux alive, waiting for CLI reconnect`);
220→      } else {
221→        // tmux session gone — agent is archived
222→        agent.status = "done";
223→        console.log(`[restore] agent ${agent.agentId} — tmux dead, archived`);
224→      }
225→    }
226→
227→    agents.set(agent.agentId, agent);
228→    const originalCount = p.messageHistory.length;
229→    const compactedCount = agent.messageHistory.length;
230→    const saved = originalCount - compactedCount;
231→    console.log(`[restore] agent ${agent.agentId} (status=${agent.status}, ${compactedCount} messages${saved > 0 ? `, compacted from ${originalCount} (−${saved})` : ""})`);
232→
233→    // Persist compacted history back to disk
234→    if (saved > 0) {
235→      persistAgentSync(agent);
236→    }
237→  }
238→  console.log(`[restore] loaded ${persisted.length} agents from disk`);
239→}
240→
241→restoreAgents();
242→
243→// ── Task restore + helpers ────────────────────────────────────────────────
244→
245→function restoreTasks() {
246→  const persisted = taskStore.loadAll();
247→  for (const t of persisted) {
248→    tasks.set(t.id, t);
249→  }
250→  console.log(`[restore] loaded ${persisted.length} tasks from disk`);
251→}
252→
253→restoreTasks();
254→
255→/** Build the full task list sorted by creation time (newest first). */
256→function buildTaskList(): Task[] {
257→  return Array.from(tasks.values()).sort((a, b) => b.createdAt - a.createdAt);
258→}
259→
260→/** Send the full task list to all browsers. */
261→function broadcastTaskList() {
262→  const payload = JSON.stringify({ type: "task_list", tasks: buildTaskList() });
263→  for (const ws of browserSockets) {
264→    if (ws.readyState === WebSocket.OPEN) {
265→      ws.send(payload);
266→    }
267→  }
268→}
269→
270→/** Persist all tasks to disk (sync). */
271→function persistTasks() {
272→  taskStore.saveSync(Array.from(tasks.values()));
273→}
274→
275→// ── Helpers ────────────────────────────────────────────────────────────────
276→
277→/** Send a JSON message to all connected browsers. */
278→function sendToBrowser(msg: ServerMessage) {
279→  const payload = JSON.stringify(msg);
280→  for (const ws of browserSockets) {
281→    if (ws.readyState === WebSocket.OPEN) {
282→      ws.send(payload);
283→    }
284→  }
285→}
286→
287→/** Build a snapshot of all agents for the sidebar. */
288→function buildAgentList(): AgentInfo[] {
289→  return Array.from(agents.values()).map((a) => ({
290→    agentId: a.agentId,
291→    status: a.status,
292→    tmuxSession: a.tmuxSession,
293→    label: a.label,
294→    createdAt: a.createdAt,
295→  }));
296→}
297→
298→/** Send the full agent list to all browsers. */
299→function broadcastAgentList() {
300→  sendToBrowser({ type: "agent_list", agents: buildAgentList() });
301→}
302→
303→/** Update an agent's status, notify browsers, broadcast list, and persist. */
304→function setAgentStatus(agentId: string, status: AgentStatus) {
305→  const agent = agents.get(agentId);
306→  if (!agent) return;
307→  agent.status = status;
308→  sendToBrowser({ type: "status", agentId, status });
309→  broadcastAgentList();
310→  persistAgentSync(agent);
311→}
312→
313→/**
314→ * Extract a stable dedup key from a relay message, if present.
315→ *
316→ * Claude NDJSON sends cumulative snapshots for two message types:
317→ * - `assistant` — keyed by `message.id` (e.g. `msg_01VE1P7c...`)
318→ * - `user` (tool_result) — keyed by top-level `uuid` (e.g. `b217b852-...`)
319→ *
320→ * We deduplicate by replacing the previous snapshot in `messageHistory`
321→ * instead of appending, reducing storage from O(n²) to O(n).
322→ */
323→function getRelayMessageId(msg: ServerMessage): string | null {
324→  if (msg.type !== "relay") return null;
325→  const inner = msg.message;
326→  if (inner.type === "assistant") {
327→    return (inner as { message?: { id?: string } }).message?.id ?? null;
328→  }
329→  if (inner.type === "user") {
330→    return (inner as { uuid?: string }).uuid ?? null;
331→  }
332→  return null;
333→}
334→
335→/**
336→ * Record a message in the agent's history and send to all browsers.
337→ *
338→ * For cumulative snapshot messages (assistant, user/tool_result), replaces the
339→ * previous snapshot with the same message ID instead of appending. This keeps
340→ * only the final version of each message, dramatically reducing file sizes
341→ * (e.g. 38 MB → ~1 MB for a typical session).
342→ */
343→function recordAndSend(agentId: string, msg: ServerMessage) {
344→  const agent = agents.get(agentId);
345→  if (agent) {
346→    const msgId = getRelayMessageId(msg);
347→    if (msgId) {
348→      // Replace previous snapshot with same message ID (search from end for speed)
349→      let replaced = false;
350→      for (let i = agent.messageHistory.length - 1; i >= 0; i--) {
351→        if (getRelayMessageId(agent.messageHistory[i]) === msgId) {
352→          agent.messageHistory[i] = msg;
353→          replaced = true;
354→          break;
355→        }
356→      }
357→      if (!replaced) {
358→        agent.messageHistory.push(msg);
359→      }
360→    } else {
361→      agent.messageHistory.push(msg);
362→    }
363→    persistAgent(agent); // debounced — streaming messages come fast
364→  }
365→  sendToBrowser(msg);
366→}
367→
368→// ── Agent lifecycle ────────────────────────────────────────────────────────
369→
370→/**
371→ * Stop a running agent by killing its tmux session and closing the CLI socket.
372→ * The agent remains in the Map (status set to "done") so it can be viewed/deleted later.
373→ */
374→function stopAgent(agentId: string) {
375→  const agent = agents.get(agentId);
376→  if (!agent) return;
377→
378→  if (agent.tmuxSession) {
379→    try {
380→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
381→      console.log(`[tmux] killed session ${agent.tmuxSession}`);
382→    } catch {
383→      // Session may already be dead
384→    }
385→  }
386→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
387→    agent.claudeSocket.close();
388→  }
389→  agent.claudeSocket = null;
390→  setAgentStatus(agentId, "done");
391→}
392→
393→/**
394→ * Permanently delete an agent: stop it, remove from Map, remove from disk.
395→ */
396→function deleteAgent(agentId: string) {
397→  const agent = agents.get(agentId);
398→  if (!agent) return;
399→
400→  if (agent.tmuxSession) {
401→    try {
402→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
403→    } catch {}
404→  }
405→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
406→    agent.claudeSocket.close();
407→  }
408→  agents.delete(agentId);
409→  store.remove(agentId);
410→  broadcastAgentList();
411→}
412→
413→/**
414→ * Spawn a new Claude CLI process inside a tmux session.
415→ *
416→ * Creates a new agent entry, spawns the CLI with `--sdk-url` pointing to
417→ * `/claude/<agentId>`, and sends a `spawned` message to the browser.
418→ */
419→function spawnClaude(prompt: string): string {
420→  const agentId = newAgentId();
421→  const sessionName = `${TMUX_SESSION_PREFIX}-${agentId}`;
422→  const label = prompt.length > 60 ? prompt.slice(0, 57) + "..." : prompt;
423→
424→  const agent: AgentState = {
425→    agentId,
426→    claudeSocket: null,
427→    tmuxSession: null,
428→    pendingPrompt: prompt,
429→    status: "spawning",
430→    label,
431→    createdAt: Date.now(),
432→    sessionId: null,
433→    pendingControlRequests: new Map(),
434→    messageHistory: [],
435→    pendingMessages: [],
436→  };
437→  agents.set(agentId, agent);
438→
439→  // Notify browsers
440→  sendToBrowser({ type: "spawned", agentId });
441→  broadcastAgentList();
442→  persistAgentSync(agent);
443→
444→  // Build the claude command with CLAUDECODE unset to bypass nesting protection.
445→  // tmux new-session runs detached (-d) so spawn() returns immediately.
446→  const claudeCmd = `unset CLAUDECODE; exec claude --dangerously-skip-permissions --sdk-url ws://localhost:${PORT}/claude/${agentId}`;
447→
448→  const tmux = spawn("tmux", ["new-session", "-d", "-s", sessionName, "bash", "-c", claudeCmd], {
449→    stdio: "ignore",
450→  });
451→
452→  tmux.on("error", (err) => {
453→    console.error("[tmux spawn error]", err);
454→    setAgentStatus(agentId, "error");
455→    recordAndSend(agentId, { type: "error", agentId, error: `tmux error: ${err.message}` });
456→  });
457→
458→  tmux.on("exit", (code) => {
459→    if (code !== 0) {
460→      console.error(`[tmux] new-session exited with code ${code}`);
461→      setAgentStatus(agentId, "error");
462→      recordAndSend(agentId, { type: "error", agentId, error: `tmux exited with code ${code}` });
463→      return;
464→    }
465→    console.log(`[tmux] session ${sessionName} created — attach with: tmux attach -t ${sessionName}`);
466→    agent.tmuxSession = sessionName;
467→    broadcastAgentList();
468→    persistAgentSync(agent);
469→  });
470→
471→  return agentId;
472→}
473→
474→// ── Message handlers ───────────────────────────────────────────────────────
475→
476→/**
477→ * Process an incoming NDJSON message from a specific Claude CLI.
478→ *
479→ * Status flow matches the Companion protocol:
480→ * - hook_response → send pending prompt → "thinking"
481→ * - system/init   → "connected" + capture session_id
482→ * - assistant      → "thinking"
483→ * - result         → "connected" (CLI stays alive for multi-turn)
484→ * - CLI disconnect → "done" (handled in connection close handler)
485→ */
486→function handleClaudeMessage(agentId: string, raw: string) {
487→  const agent = agents.get(agentId);
488→  if (!agent) return;
489→
490→  let msg: ClaudeMessage;
491→  try {
492→    msg = JSON.parse(raw);
493→  } catch {
494→    console.error(`[claude:${agentId}] invalid JSON:`, raw);
495→    return;
496→  }
497→
498→  // Silently ignore keep_alive messages
499→  if (msg.type === "keep_alive") return;
500→
501→  console.log(`[claude:${agentId} →]`, msg.type, (msg as { subtype?: string }).subtype ?? "");
502→
503→  // After hook_response, send the pending prompt
504→  if (
505→    msg.type === "system" &&
506→    (msg as { subtype?: string }).subtype === "hook_response" &&
507→    agent.pendingPrompt &&
508→    agent.claudeSocket?.readyState === WebSocket.OPEN
509→  ) {
510→    const userMsg = JSON.stringify({
511→      type: "user",
512→      message: { role: "user", content: agent.pendingPrompt },
513→      parent_tool_use_id: null,
514→      session_id: agent.sessionId ?? "",
515→    });
516→    console.log(`[server → claude:${agentId}]`, userMsg);
517→    agent.claudeSocket.send(userMsg + "\n");
518→    agent.pendingPrompt = null;
519→    setAgentStatus(agentId, "thinking");
520→  }
521→
522→  // Track status based on message type
523→  if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
524→    // Capture session_id for subsequent user messages
525→    agent.sessionId = (msg as { session_id?: string }).session_id ?? null;
526→    setAgentStatus(agentId, "connected");
527→  } else if (msg.type === "assistant") {
528→    setAgentStatus(agentId, "thinking");
529→  } else if (msg.type === "result") {
530→    // CLI stays alive after result — ready for the next turn.
531→    // Status only goes to "done" when the CLI WebSocket actually closes.
532→    setAgentStatus(agentId, "connected");
533→  }
534→
535→  // Store control_request inputs for building proper responses later
536→  if (msg.type === "control_request") {
537→    const cr = msg as { request_id?: string; request?: { input?: Record<string, unknown> } };
538→    if (cr.request_id && cr.request?.input) {
539→      agent.pendingControlRequests.set(cr.request_id, cr.request.input);
540→    }
541→  }
542→
543→  // Record in history and relay to browsers
544→  recordAndSend(agentId, { type: "relay", agentId, message: msg });
545→}
546→
547→/**
548→ * Process an incoming JSON message from the browser.
549→ * - `spawn`: create a new agent (does NOT kill others).
550→ * - `send_message`: forward a follow-up user message to the specified agent.
551→ * - `control_response`: forward a tool allow/deny decision to the specified agent.
552→ * - `kill_agent`: stop the CLI and tmux session.
553→ * - `delete_agent`: permanently remove an agent.
554→ * - `rename_agent`: update an agent's label.
555→ * - `clear_history`: wipe an agent's message history.
556→ * - `request_history`: send message history for a single agent (lazy loading).
557→ * - `create_task` / `update_task` / `delete_task` / `delegate_task`: task CRUD.
558→ */
559→function handleBrowserMessage(raw: string, senderWs: WebSocket) {
560→  let msg: BrowserMessage;
561→  try {
562→    msg = JSON.parse(raw);
563→  } catch {
564→    console.error("[browser] invalid JSON:", raw);
565→    return;
566→  }
567→
568→  console.log("[browser →]", msg.type);
569→
570→  switch (msg.type) {
571→    case "spawn":
572→      spawnClaude(msg.prompt);
573→      break;
574→
575→    case "send_message": {
576→      const agent = agents.get(msg.agentId);
577→      if (!agent) {
578→        sendToBrowser({ type: "error", agentId: msg.agentId, error: "Unknown agent" });
579→        break;
580→      }
581→
582→      // Record the user message in history so it persists across reloads.
583→      // Do NOT broadcast — the sending browser already has it optimistically,
584→      // and other browsers will get it when they request_history.
585→      agent.messageHistory.push({
586→        type: "relay",
587→        agentId: msg.agentId,
588→        message: { type: "user", message: { role: "user", content: msg.content } },
589→      } as ServerMessage);
590→      persistAgent(agent);
591→
592→      if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
593→        const userMsg = JSON.stringify({
594→          type: "user",
595→          message: { role: "user", content: msg.content },
596→          parent_tool_use_id: null,
597→          session_id: agent.sessionId ?? "",
598→        });
599→        agent.claudeSocket.send(userMsg + "\n");
600→        setAgentStatus(msg.agentId, "thinking");
601→      } else {
602→        // Queue message for delivery when CLI reconnects
603→        const userMsg = JSON.stringify({
604→          type: "user",
605→          message: { role: "user", content: msg.content },
606→          parent_tool_use_id: null,
607→          session_id: agent.sessionId ?? "",
608→        });
609→        agent.pendingMessages.push(userMsg);
610→        console.log(`[queue] queued message for agent ${msg.agentId} (${agent.pendingMessages.length} pending)`);
611→        persistAgentSync(agent);
612→      }
613→      break;
614→    }
615→
616→    case "control_response": {
617→      const agent = agents.get(msg.agentId);
618→      if (agent?.claudeSocket?.readyState === WebSocket.OPEN) {
619→        // Retrieve the original tool input to include as updatedInput (required by protocol)
620→        const originalInput = agent.pendingControlRequests.get(msg.request_id) ?? {};
621→        agent.pendingControlRequests.delete(msg.request_id);
622→
623→        // If the browser sent answers (from AskUserQuestion), merge them into the input
624→        const answers = (msg as { answers?: Record<string, string> }).answers;
625→        const updatedInput = answers
626→          ? { ...originalInput, answers }
627→          : originalInput;
628→
629→        const response = JSON.stringify({
630→          type: "control_response",
631→          response: {
632→            subtype: "success",
633→            request_id: msg.request_id,
634→            response: msg.allow
635→              ? { behavior: "allow", updatedInput }
636→              : { behavior: "deny", message: "Denied by user" },
637→          },
638→        });
639→        agent.claudeSocket.send(response + "\n");
640→      }
641→      break;
642→    }
643→
644→    case "kill_agent":
645→      stopAgent(msg.agentId);
646→      break;
647→
648→    case "delete_agent":
649→      deleteAgent(msg.agentId);
650→      break;
651→
652→    case "rename_agent": {
653→      const agent = agents.get(msg.agentId);
654→      if (!agent) break;
655→      agent.label = msg.label;
656→      broadcastAgentList();
657→      persistAgentSync(agent);
658→      break;
659→    }
660→
661→    case "clear_history": {
662→      const agent = agents.get(msg.agentId);
663→      if (!agent) break;
664→      agent.messageHistory = [];
665→      persistAgentSync(agent);
666→      sendToBrowser({ type: "history_cleared", agentId: msg.agentId });
667→      break;
668→    }
669→
670→    case "request_history": {
671→      console.log(`[browser] request_history for ${msg.agentId}`);
672→      sendHistoryToSocket(senderWs, msg.agentId);
673→      break;
674→    }
675→
676→    case "create_task": {
677→      const taskId = randomBytes(4).toString("hex");
678→      const task: Task = {
679→        id: taskId,
680→        title: msg.title,
681→        description: msg.description,
682→        status: "todo",
683→        priority: msg.priority,
684→        agentId: null,
685→        createdAt: Date.now(),
686→        updatedAt: Date.now(),
687→      };
688→      tasks.set(taskId, task);
689→      persistTasks();
690→      broadcastTaskList();
691→      break;
692→    }
693→
694→    case "update_task": {
695→      const task = tasks.get(msg.taskId);
696→      if (!task) break;
697→      Object.assign(task, msg.updates, { updatedAt: Date.now() });
698→      persistTasks();
699→      broadcastTaskList();
700→      break;
701→    }
702→
703→    case "delete_task": {
704→      tasks.delete(msg.taskId);
705→      persistTasks();
706→      broadcastTaskList();
707→      break;
708→    }
709→
710→    case "delegate_task": {
711→      const task = tasks.get(msg.taskId);
712→      if (!task) break;
713→      const prompt = `Task: ${task.title}\n\n${task.description}`;
714→      const agentId = spawnClaude(prompt);
715→      task.agentId = agentId;
716→      task.status = "in-progress";
717→      task.updatedAt = Date.now();
718→      persistTasks();
719→      broadcastTaskList();
720→      break;
721→    }
722→  }
723→}
724→
725→// ── Send message history to a single browser socket ────────────────────────
726→
727→/** Send initial state (agent list + tasks) to a newly connected browser. */
728→function sendFullStateToSocket(ws: WebSocket) {
729→  if (ws.readyState !== WebSocket.OPEN) return;
730→
731→  // Agent list (sidebar metadata) — message histories are loaded lazily on demand
732→  ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList() }));
733→
734→  // Task list
735→  ws.send(JSON.stringify({ type: "task_list", tasks: buildTaskList() }));
736→}
737→
738→/** Send message history for a single agent to a specific browser socket. */
739→function sendHistoryToSocket(ws: WebSocket, agentId: string) {
740→  const agent = agents.get(agentId);
741→  if (!agent || ws.readyState !== WebSocket.OPEN) return;
742→  ws.send(
743→    JSON.stringify({
744→      type: "message_history",
