751→// ── Connection handler — route by URL path ────────────────────────────────
752→wss.on("connection", (ws: WebSocket, req: IncomingMessage) => {
753→  const path = req.url ?? "/";
754→  console.log(`[ws connected] path=${path}`);
755→
756→  if (path === "/browser") {
757→    // Send full state BEFORE adding to browserSockets so that live
758→    // relay broadcasts don't interleave with the history replay.
759→    sendFullStateToSocket(ws);
760→    browserSockets.add(ws);
761→
762→    ws.on("message", (data) => {
763→      handleBrowserMessage(data.toString(), ws);
764→    });
765→
766→    ws.on("close", () => {
767→      console.log("[browser disconnected]");
768→      browserSockets.delete(ws);
769→      // Do NOT kill agents — keep them alive for reconnect
770→    });
771→  } else if (path.startsWith("/claude/")) {
772→    // Parse agentId from /claude/<agentId>
773→    const agentId = path.slice("/claude/".length);
774→    const agent = agents.get(agentId);
775→
776→    if (!agent) {
777→      console.log(`[ws] unknown agentId: ${agentId}, closing`);
778→      ws.close();
779→      return;
780→    }
781→
782→    agent.claudeSocket = ws;
783→    console.log(`[claude:${agentId} CLI connected via WebSocket]`);
784→
785→    // Notify browsers that CLI is connected
786→    sendToBrowser({ type: "cli_connected", agentId });
787→
788→    // Flush any pending messages queued while CLI was disconnected
789→    if (agent.pendingMessages.length > 0) {
790→      console.log(`[flush] sending ${agent.pendingMessages.length} queued messages to agent ${agentId}`);
791→      for (const queued of agent.pendingMessages) {
792→        ws.send(queued + "\n");
793→      }
794→      agent.pendingMessages = [];
795→      persistAgentSync(agent);
796→    }
797→
798→    // Send the pending prompt immediately — CLI 2.1.42+ waits for the
799→    // server to send the first user message rather than emitting
800→    // hook_started/hook_response on connect.
801→    if (agent.pendingPrompt && ws.readyState === WebSocket.OPEN) {
802→      const userMsg = JSON.stringify({
803→        type: "user",
804→        message: { role: "user", content: agent.pendingPrompt },
805→        parent_tool_use_id: null,
806→        session_id: agent.sessionId ?? "",
807→      });
808→      console.log(`[server → claude:${agentId}] sending pending prompt`);
809→      ws.send(userMsg + "\n");
810→      agent.pendingPrompt = null;
811→      setAgentStatus(agentId, "thinking");
812→    }
813→
814→    ws.on("message", (data) => {
815→      handleClaudeMessage(agentId, data.toString());
816→    });
817→
818→    ws.on("close", () => {
819→      console.log(`[claude:${agentId} CLI disconnected]`);
820→      if (agent.claudeSocket === ws) {
821→        agent.claudeSocket = null;
822→        if (agent.status !== "error") {
823→          setAgentStatus(agentId, "done");
824→          sendToBrowser({ type: "cli_disconnected", agentId });
825→
826→          // Auto-complete any task linked to this agent
827→          for (const task of tasks.values()) {
828→            if (task.agentId === agentId && task.status !== "done") {
829→              task.status = "done";
830→              task.updatedAt = Date.now();
831→              persistTasks();
832→              broadcastTaskList();
833→              break;
834→            }
835→          }
836→        }
837→      }
838→    });
839→  } else {
840→    console.log(`[ws] unknown path: ${path}, closing`);
841→    ws.close();
842→  }
843→});
844→
845→// ── Graceful shutdown ─────────────────────────────────────────────────────
846→
847→function shutdown() {
848→  console.log("[ws server] shutting down...");
849→
850→  // Persist all agents synchronously before exit — do NOT kill tmux sessions
851→  // so CLI processes can reconnect if the server restarts.
852→  const allPersisted = Array.from(agents.values()).map(toPersistedAgent);
853→  store.flushAll(allPersisted);
854→  console.log(`[ws server] saved ${allPersisted.length} agents to disk (tmux sessions preserved)`);
855→
856→  taskStore.flush(Array.from(tasks.values()));
857→  console.log(`[ws server] saved ${tasks.size} tasks to disk`);
858→
859→  wss.close();
860→  process.exit(0);
861→}
862→
863→process.on("SIGTERM", shutdown);
864→process.on("SIGINT", shutdown);
865→
