    // Capture session_id for subsequent user messages
    agent.sessionId = (msg as { session_id?: string }).session_id ?? null;
    setAgentStatus(agentId, "connected");
  } else if (msg.type === "assistant") {
    setAgentStatus(agentId, "thinking");
