/**
 * Shared type definitions for the thos dashboard.
 *
 * Three categories:
 * 1. **Claude NDJSON protocol** — messages the Claude CLI sends over its
 *    `--sdk-url` WebSocket connection (CLI → WS server).
 * 2. **Browser ↔ Server** — messages exchanged between the React client
 *    and the standalone WS relay server.
 * 3. **UI state** — view-model types consumed by React components.
 *
 * ## Key architecture notes
 *
 * - On browser connect, the server sends `agent_list` + `task_list` only.
 * - Message histories are loaded lazily: the browser sends
 *   `request_history` when selecting an agent, and the server responds
 *   with `message_history` for that single agent.
 * - Live messages for active agents are broadcast via `relay` in real time.
 * - See `server/ws.ts` and `hooks/use-websocket.ts` for implementation.
 */

// ── Claude NDJSON protocol messages (CLI → server) ────────────────────────

/**
 * Sent once after the first user prompt is received. Contains session
 * metadata like the model name, working directory, and available tools.
 */
export interface ClaudeSystemInit {
  type: "system";
  subtype: "init";
  session_id: string;
  tools: unknown[];
  mcp_servers: unknown[];
  model: string;
  cwd: string;
}

/**
 * An assistant turn. `message.content` is an array of content blocks
 * (text, tool_use, tool_result) that may arrive incrementally — each
 * NDJSON line is a complete snapshot of the message so far.
 */
export interface ClaudeAssistant {
  type: "assistant";
  message: {
    id: string;
    role: "assistant";
    content: AssistantContentBlock[];
    model: string;
    stop_reason: string | null;
  };
  session_id: string;
}

/** A single content block inside an assistant message. */
export type AssistantContentBlock =
  | { type: "text"; text: string }
  | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> }
  | { type: "tool_result"; tool_use_id: string; content: string };

/**
 * Terminal message for a session. Includes cost/duration metrics.
 * `is_error` is true when `subtype` is `"error"`.
 */
export interface ClaudeResult {
  type: "result";
  subtype: "success" | "error";
  result?: string;
  error?: string;
  session_id: string;
  cost_usd: number;
  duration_ms: number;
  duration_api_ms: number;
  is_error: boolean;
  num_turns: number;
}

/**
 * Claude is requesting permission to execute a tool. The dashboard must
 * reply with a `control_response` (allow / deny) before the CLI proceeds.
 *
 * Wire format uses a nested `request` object with `request_id` at the
 * top level for correlation (matches Companion protocol docs).
 */
export interface ClaudeControlRequest {
  type: "control_request";
  request_id: string;
  request: {
    subtype: "can_use_tool";
    tool_name: string;
    input: Record<string, unknown>;
    tool_use_id?: string;
    description?: string;
  };
  session_id?: string;
}

/**
 * Hook lifecycle events emitted during CLI startup. `hook_response` is
 * the signal that the CLI is ready to receive the first user prompt.
 */
export interface ClaudeSystemHook {
  type: "system";
  subtype: "hook_started" | "hook_response";
  session_id?: string;
}

/** Discriminated union of all known Claude NDJSON message shapes. */
export type ClaudeMessage =
  | ClaudeSystemInit
  | ClaudeAssistant
  | ClaudeResult
  | ClaudeControlRequest
  | ClaudeSystemHook
  | { type: string; subtype?: string; [key: string]: unknown };

// ── Workspaces ───────────────────────────────────────────────────────────

/** A workspace represents a project directory. */
export interface Workspace {
  id: string;
  name: string;
  cwd: string;
  createdAt: number;
}

/** A directory entry returned by the server-side folder browser. */
export interface DirectoryEntry {
  name: string;
  path: string;
}

// ── Browser ↔ Server messages ─────────────────────────────────────────────

/** Browser asks the server to spawn a new Claude CLI process. */
export interface BrowserSpawn {
  type: "spawn";
  prompt: string;
  workspaceId?: string;
}

/** Browser sends a follow-up message to an already-running Claude session. */
export interface BrowserSendMessage {
  type: "send_message";
  agentId: string;
  content: string;
}

/** Browser responds to a tool approval request (allow or deny). */
export interface BrowserControlResponse {
  type: "control_response";
  agentId: string;
  request_id: string;
  allow: boolean;
}

/** Browser asks the server to kill a running agent's tmux session + CLI. */
export interface BrowserKillAgent {
  type: "kill_agent";
  agentId: string;
}

/** Browser asks the server to permanently delete an agent. */
export interface BrowserDeleteAgent {
  type: "delete_agent";
  agentId: string;
}

/** Browser asks the server to rename an agent. */
export interface BrowserRenameAgent {
  type: "rename_agent";
  agentId: string;
  label: string;
}

/** Browser asks the server to clear an agent's message history. */
export interface BrowserClearHistory {
  type: "clear_history";
  agentId: string;
}

/** Browser requests message history for a specific agent (lazy loading). */
export interface BrowserRequestHistory {
  type: "request_history";
  agentId: string;
}

/** Browser asks the server to create a new task. */
export interface BrowserCreateTask {
  type: "create_task";
  title: string;
  description: string;
  priority: TaskPriority;
}

/** Browser asks to update a task's fields. */
export interface BrowserUpdateTask {
  type: "update_task";
  taskId: string;
  updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>;
}

/** Browser asks to delete a task. */
export interface BrowserDeleteTask {
  type: "delete_task";
  taskId: string;
}

/** Browser asks to delegate a task to a new Claude agent. */
export interface BrowserDelegateTask {
  type: "delegate_task";
  taskId: string;
}

/** Browser tells the server which workspace to scope to. */
export interface BrowserSetWorkspace {
  type: "set_workspace";
  workspaceId: string | null;
}

/** Browser asks the server to create a new workspace. */
export interface BrowserCreateWorkspace {
  type: "create_workspace";
  name: string;
  cwd: string;
}

/** Browser asks to rename a workspace. */
export interface BrowserRenameWorkspace {
  type: "rename_workspace";
  workspaceId: string;
  name: string;
}

/** Browser asks to delete a workspace. */
export interface BrowserDeleteWorkspace {
  type: "delete_workspace";
  workspaceId: string;
}

/** Browser asks to browse a directory on the server. */
export interface BrowserBrowseDirectory {
  type: "browse_directory";
  path: string;
}

/** Union of all messages the browser can send to the WS server. */
export type BrowserMessage =
  | BrowserSpawn
  | BrowserSendMessage
  | BrowserControlResponse
  | BrowserKillAgent
  | BrowserDeleteAgent
  | BrowserRenameAgent
  | BrowserClearHistory
  | BrowserRequestHistory
  | BrowserCreateTask
  | BrowserUpdateTask
  | BrowserDeleteTask
  | BrowserDelegateTask
  | BrowserSetWorkspace
  | BrowserCreateWorkspace
  | BrowserRenameWorkspace
  | BrowserDeleteWorkspace
  | BrowserBrowseDirectory;

/** Server relays a raw Claude NDJSON message to the browser. */
export interface ServerRelay {
  type: "relay";
  agentId: string;
  message: ClaudeMessage;
}

/** Server notifies the browser of an agent status change. */
export interface ServerStatus {
  type: "status";
  agentId: string;
  status: AgentStatus;
}

/** Server reports an error (e.g. no active session, process crash). */
export interface ServerError {
  type: "error";
  agentId: string;
  error: string;
}

/** Summary of an agent for the sidebar. */
export interface AgentInfo {
  agentId: string;
  status: AgentStatus;
  tmuxSession: string | null;
  label: string;
  createdAt: number;
  workspaceId: string | null;
}

/** Server sends the full list of agents after every state change. */
export interface ServerAgentList {
  type: "agent_list";
  agents: AgentInfo[];
}

/** Server confirms a new agent was spawned and assigns its ID. */
export interface ServerSpawned {
  type: "spawned";
  agentId: string;
}

/** Server sends full message history for an agent (in response to `request_history`). */
export interface ServerMessageHistory {
  type: "message_history";
  agentId: string;
  messages: ServerMessage[];
}

/** CLI WebSocket disconnected (process may have crashed or exited). */
export interface ServerCliDisconnected {
  type: "cli_disconnected";
  agentId: string;
}

/** CLI WebSocket reconnected (e.g. after relaunch with --resume). */
export interface ServerCliConnected {
  type: "cli_connected";
  agentId: string;
}

/** Server confirms message history was cleared for an agent. */
export interface ServerHistoryCleared {
  type: "history_cleared";
  agentId: string;
}

/** Server sends the full workspace list to the browser. */
export interface ServerWorkspaceList {
  type: "workspace_list";
  workspaces: Workspace[];
}

/** Server responds with a directory listing for the folder browser. */
export interface ServerDirectoryListing {
  type: "directory_listing";
  path: string;
  entries: DirectoryEntry[];
}

/** Server sends the full task list to the browser. */
export interface ServerTaskList {
  type: "task_list";
  tasks: Task[];
}

/** Server confirms a task was updated. */
export interface ServerTaskUpdated {
  type: "task_updated";
  task: Task;
}

/** Server confirms a task was deleted. */
export interface ServerTaskDeleted {
  type: "task_deleted";
  taskId: string;
}

/** Union of all messages the WS server can send to the browser. */
export type ServerMessage =
  | ServerRelay
  | ServerStatus
  | ServerError
  | ServerAgentList
  | ServerSpawned
  | ServerMessageHistory
  | ServerCliDisconnected
  | ServerCliConnected
  | ServerHistoryCleared
  | ServerWorkspaceList
  | ServerDirectoryListing
  | ServerTaskList
  | ServerTaskUpdated
  | ServerTaskDeleted;

// ── UI state ──────────────────────────────────────────────────────────────

/**
 * Lifecycle states of the Claude agent process:
 * - `idle`      — no process running, ready to spawn
 * - `spawning`  — process launched, waiting for CLI to connect via WS
 * - `connected` — CLI connected and `system/init` received
 * - `thinking`  — waiting for assistant response
 * - `done`      — `result` message received, process finished
 * - `error`     — process crashed or unexpected failure
 */
export type AgentStatus = "idle" | "spawning" | "connected" | "thinking" | "done" | "disconnected" | "error";

export type ChatMessageRole = "user" | "assistant" | "system";

/**
 * A single entry in the chat message list. System messages include
 * session init info and result summaries. Messages with a `controlRequest`
 * are rendered as tool-approval cards instead of plain bubbles.
 */
/** A single option in an AskUserQuestion question. */
export interface UserQuestionOption {
  label: string;
  description?: string;
}

/** A single question from AskUserQuestion. */
export interface UserQuestion {
  question: string;
  header?: string;
  options: UserQuestionOption[];
  multiSelect: boolean;
}

/** Info about a single tool_use block in an assistant message. */
export interface ToolCallInfo {
  name: string;
  toolUseId?: string;
}

export interface ChatMessage {
  id: string;
  role: ChatMessageRole;
  content: string;
  timestamp: number;
  /** Present when this message represents a tool approval request. */
  controlRequest?: {
    id: string;
    tool_name: string;
    input: Record<string, unknown>;
    /** Set to true after the user allows or denies. */
    resolved?: boolean;
  };
  /** Present when this message is an AskUserQuestion control request. */
  userQuestion?: {
    requestId: string;
    questions: UserQuestion[];
    resolved?: boolean;
  };
  /** Tool calls found in this assistant message. */
  toolCalls?: ToolCallInfo[];
  /** True when this message has only tool_use/tool_result blocks and no text. */
  isToolOnly?: boolean;
}

// ── Task system ──────────────────────────────────────────────────────────

export type TaskStatus = "todo" | "in-progress" | "done";
export type TaskPriority = "low" | "medium" | "high" | "urgent";

/** A user-created task, optionally linked to a Claude agent. */
export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  priority: TaskPriority;
  /** If delegated, the agentId of the spawned Claude agent. */
  agentId: string | null;
  /** Workspace this task belongs to. */
  workspaceId: string | null;
  createdAt: number;
  updatedAt: number;
}

